INSERT INTO roles (id, nombre, descripcion) VALUES
  (1, 'Administrador', 'Control total del sistema, reportes y precios'),
  (2, 'Gerente', 'Supervisión de operación, proveedores e inventario'),
  (3, 'Cajero', 'Registro de ventas y emisión de comprobantes'),
  (4, 'Inventario', 'Gestión de productos, compras y movimientos de stock'),
  (5, 'Supervisor de turno', 'Coordina el turno y apoya la caja (sin permisos asignados)'),
  (6, 'Jefe de cocina', 'Dirige la producción y la calidad de la cocina (sin permisos asignados)'),
  (7, 'Cocinero', 'Prepara empanadas, arepas y fritos (sin permisos asignados)'),
  (8, 'Auxiliar de cocina', 'Apoya la preparación y el alistamiento (sin permisos asignados)'),
  (9, 'Mesero', 'Atiende las mesas del local (sin permisos asignados)'),
  (10, 'Domiciliario', 'Entrega los pedidos a domicilio (sin permisos asignados)'),
  (11, 'Bodeguero', 'Recibe y organiza la mercancía en bodega (sin permisos asignados)'),
  (12, 'Comprador', 'Negocia y programa las compras con proveedores (sin permisos asignados)'),
  (13, 'Contador', 'Revisa la contabilidad y los impuestos (sin permisos asignados)'),
  (14, 'Auditor interno', 'Verifica procesos, inventario y caja (sin permisos asignados)'),
  (15, 'Mercadeo', 'Diseña promociones y campañas de la marca (sin permisos asignados)'),
  (16, 'Talento humano', 'Gestiona contratación, turnos y nómina (sin permisos asignados)'),
  (17, 'Soporte técnico', 'Mantiene los equipos y el sistema (sin permisos asignados)'),
  (18, 'Cajero suplente', 'Cubre la caja en ausencia del cajero titular (sin permisos asignados)'),
  (19, 'Practicante', 'Estudiante en práctica en el punto de venta (sin permisos asignados)'),
  (20, 'Aseo y mantenimiento', 'Mantiene limpio y en orden el local (sin permisos asignados)'),
  (21, 'Seguridad', 'Vigila el local y el manejo del efectivo (sin permisos asignados)'),
  (22, 'Control de calidad', 'Revisa materias primas y producto terminado (sin permisos asignados)'),
  (23, 'Gerente de zona', 'Supervisa varios puntos de venta de la marca (sin permisos asignados)'),
  (24, 'Franquiciado', 'Opera un punto de venta bajo la marca (sin permisos asignados)'),
  (25, 'Consulta', 'Acceso de solo lectura para revisiones externas (sin permisos asignados)');
